import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Widget-Sprachen, HA-Quellen und Climate","description":"DE/EN/FR, Attributquellen, Einheiten und optionale Climate-Steuerung ab Studio 0.1.296.","frontmatter":{"title":"Widget-Sprachen, HA-Quellen und Climate","description":"DE/EN/FR, Attributquellen, Einheiten und optionale Climate-Steuerung ab Studio 0.1.296."},"headers":[],"relativePath":"projects/grafik-visual-studio/ha-quellen-climate.md","filePath":"projects/grafik-visual-studio/ha-quellen-climate.md","lastUpdated":1792862520000}'),a={name:"projects/grafik-visual-studio/ha-quellen-climate.md"};function l(s,e,u,d,h,o){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="widget-sprachen-ha-quellen-und-climate" tabindex="-1">Widget-Sprachen, HA-Quellen und Climate <a class="header-anchor" href="#widget-sprachen-ha-quellen-und-climate" aria-label="Permalink to &quot;Widget-Sprachen, HA-Quellen und Climate&quot;">​</a></h1><p>Ab <strong>Studio 0.1.296</strong> erhalten die restlichen <strong>62 Widgettypen</strong> (Spezial, Messinstrumente, Datenfluss und sieben mitgelieferte Pakete) Widget-Eigenschaften und Laufzeitmeldungen in <strong>DE/EN/FR</strong>. Die allgemeine Studio-Oberfläche bleibt DE/EN. <a href="/en/projects/grafik-visual-studio/ha-quellen-climate">English</a> · <a href="/fr/projects/grafik-visual-studio/ha-quellen-climate">Français</a>.</p><h2 id="sprache-wahlen" tabindex="-1">Sprache wählen <a class="header-anchor" href="#sprache-wahlen" aria-label="Permalink to &quot;Sprache wählen&quot;">​</a></h2><p>In den Projekteinstellungen legt <strong>Widget-Sprache</strong> den Standard fest. Die gleichnamige Widget-Gruppe kann ihn überschreiben. Calendar+, Energy, Industrial, Printer, Solar, Technic und Weather/Heating funktionieren mit ihren bisherigen Paketversionen. Eigene Beschriftungen, Entitäts-IDs und gespeicherte Schlüssel werden nicht übersetzt oder umgeschrieben.</p><h2 id="ha-quelle-prufen" tabindex="-1">HA-Quelle prüfen <a class="header-anchor" href="#ha-quelle-prufen" aria-label="Permalink to &quot;HA-Quelle prüfen&quot;">​</a></h2><p>Bei gebundenen lesenden Entitäten erscheint die zunächst deaktivierte Gruppe <strong>HA-Quellen und Einheiten</strong>. Ein leeres Attribut liest den Zustand; alternativ kann ein Attribut eingetragen werden. <strong>Quelle prüfen</strong> aktualisiert den Wert, entdeckt verfügbare Attributnamen und zeigt Einheit, fehlende Daten oder inkompatible Umrechnung an. Bei strukturierten Werten wird auf die JSON-Struktur hingewiesen. Das ausgewählte Attribut muss zur erwarteten Widget-Struktur passen.</p><p>Automatische Einheitenumrechnung ist freiwillig. Bei Energy ersetzt sie den bisherigen Faktor für diese Quelle, ohne die alte Einstellung zu löschen. Feste Anzeigen/Berechnungen richten sich nach der Widget-Einheit: Solar W/°C/%, Batterieenergie kWh, Climate native Temperatur-Einheit. Dort ist das Zieleinheitenfeld gesperrt. Bei frei konfigurierbaren Quellen sind kompatible Leistungs-, Energie-, Temperatur-, Preis-, Längen-, Volumen-, Geschwindigkeits- und Druckeinheiten möglich. Fehlende Metadaten und inkompatible Einheiten ergeben einen unbekannten Wert. Native HA-Schreibziele bleiben unverändert.</p><p>Energy kann ausgewählte numerische Recorder-Attribute lesen. Fehlende Attribute erzeugen Lücken. Unterschiedliche Verlaufsattribute derselben Entität benötigen getrennte Verlaufwidgets. C/F-Umrechnung mit Offset wird auf Energy-Verläufe nicht angewendet. Die separate Thermostat-Verlaufansicht behält ihre nativen HA-Quellen; Quellenoptionen wirken dort auf die Live-Anzeige. Recorder ersetzt nicht die vollständige native Energieverwaltung oder deren Langzeitstatistiken.</p><h2 id="climate-steuerung" tabindex="-1">Climate-Steuerung <a class="header-anchor" href="#climate-steuerung" aria-label="Permalink to &quot;Climate-Steuerung&quot;">​</a></h2><p>Beim <strong>Technic Thermostat – Temperature</strong> zunächst <strong>Climate-Steuerung</strong> aktivieren und die benötigten Optionen einschalten:</p><ul><li>Heiz-/Kühlbereich mit zwei Sollwerten und gemeinsamem Übernehmen.</li><li>Betriebsart und Voreinstellung.</li><li>Lüftermodus, vertikales und horizontales Schwenken.</li><li>Soll-Feuchtigkeit sowie Ein/Aus.</li></ul><p>Die Runtime bietet ausschließlich vom Gerät gemeldete Funktionen/Werte an. Grenzen und Schrittweite werden auch serverseitig erneut geprüft. Der vorhandene einzelne Sollwert bleibt erhalten; Geräte mit ausschließlich zwei Sollwerten verwenden die Bereichssteuerung. Im Editor, bei Schreibschutz und unbekannten Zuständen bleiben die Bedienelemente gesperrt. Bei vielen Optionen das Widget ausreichend vergrößern; im kleinen Widget scrollt der Zusatzbereich.</p><p>Neue Gruppen starten deaktiviert. Bestehende Projekte, Gruppen und Faktoren bleiben gültig. Ein erfolgreicher Serviceaufruf bestätigt die Übergabe an HA, nicht den physischen Gerätezustand. Reale Geräte, Ingress/Companion, externe Einbettungen und Benachrichtigungszustellung müssen an der Installation geprüft werden.</p><p><a href="https://www.home-assistant.io/integrations/climate/" target="_blank" rel="noreferrer">HA Climate</a> · <a href="https://developers.home-assistant.io/docs/core/entity/climate/" target="_blank" rel="noreferrer">Gerätefähigkeiten</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Prüfbericht</a></p>',14)])])}const p=t(a,[["render",l]]);export{c as __pageData,p as default};
